'use client';
const require_details = require("./details.cjs");
const require_details_content = require("./details-content.cjs");
const require_details_summary = require("./details-summary.cjs");
//#region src/components/details/index.ts
/**
* Details component, contains `Details.Summary` and `Details.Content` components.
*
* @example
* <Details>
*  <Details.Summary>Header</Details.Summary>
*  <Details.Content>Content</Details.Content>
* </Details>
*/
const DetailsComponent = Object.assign(require_details.Details, {
	Summary: require_details_summary.DetailsSummary,
	Content: require_details_content.DetailsContent
});
DetailsComponent.Summary.displayName = "Details.Summary";
DetailsComponent.Content.displayName = "Details.Content";
//#endregion
exports.Details = DetailsComponent;
exports.DetailsContent = require_details_content.DetailsContent;
exports.DetailsSummary = require_details_summary.DetailsSummary;
